//! Independent ordinary rune altar World actions; pinned Wiki recipe facts, no developer tests invoked.
use gielinor_world::{simulation::{World,PlayerData,ActorId,Action,WorldEvent},runecrafting::{Config,Recipe},locations::Location,loc_collision::{self,LocCollision},inventory::Item,stats::Stats,npc::RandomSource,hits::{Hit,Target,Style},CoordGrid};
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("ordinary rune binding unexpectedly drew RNG")}}
const ROWS:[(u32,i32,u8,u16,u8);6]=[(34760,556,1,50,11),(34761,558,2,55,14),(34762,555,5,60,19),(34763,557,9,65,26),(34764,554,14,70,35),(34765,559,20,75,46)];
fn fixture(row:usize,member:bool,kind:usize,current:u8,count:usize,rate:i32)->(World,ActorId,Location,Vec<(usize,i32)>){let(id,output,level,xp,interval)=ROWS[row];let mut w=World::default();for x in [3216,3224]{for z in [3216,3224]{w.collision.allocate(x,z,0);}}let location=Location::new(CoordGrid::new(3221,3220,0).unwrap(),id,10,0).unwrap();let ty=LocCollision{width:3,length:3,block_walk:2,block_range:true,break_route_finding:false};w.location_types.insert(id,ty);w.locations.load(location);loc_collision::toggle(&mut w.collision,location.coords,location.shape,location.angle,ty,true).unwrap();w.runecrafting=Some(Config{altars:[(id,Recipe{output,level,xp_tenths:xp,interval,name:"independent rune"})].into(),blocked_held:[24704,26879,28593,28595,28597,28599].into(),blocked_worn:[26822, 26824, 26826, 26828, 26830, 26832, 26834, 26836, 26838, 26840, 26842, 26844, 26846, 26848, 26850, 26852, 26854, 26856, 26858, 26860, 26862, 26864, 26866, 26868, 26870, 26872, 26874].into(),animation:791,spot:186});w.object_types.stackable.insert(output);let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(20,99);stats.set_current(20,current as i8);stats.set_fine_xp(20,130344311).unwrap();let mut d=PlayerData::new(1,"Independent rune binder".into(),CoordGrid::new(3220,3220,0).unwrap(),stats);d.xp_rate_hundreds=rate;for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:if s==27{995}else{1931},count:if s==27{1000}else{1},vars:0})).unwrap();}let mut parts=vec![];for k in 0..count{let slot=(k*9+7)%28;let id=match kind{0=>1436,1=>7936,_=>if k%2==0{1436}else{7936}};d.inventory.restore_slot(slot,Some(Item{id,count:1,vars:0})).unwrap();parts.push((slot,id));}d.equipment.restore_slot(0,Some(Item{id:1155,count:1,vars:7})).unwrap();d.equipment.restore_slot(4,Some(Item{id:1129,count:1,vars:9})).unwrap();w.queue_login(1,d).unwrap();w.tick_with_random(&mut NoDraw).unwrap();let actor=w.actors().next().unwrap();w.set_membership(actor,member).unwrap();w.drain_events();(w,actor,location,parts)}
fn request(w:&mut World,a:ActorId,location:Location){assert!(w.has_location_handler(location.id,1));assert!(!w.has_location_handler(location.id,2));w.submit(a,Action::OperateLocation{coords:location.coords,id:location.id,operation:1,control:false}).unwrap();w.tick_with_random(&mut NoDraw).unwrap();}
fn attempt(w:&mut World,a:ActorId,loc:Location,op:u8){let _=w.submit(a,Action::OperateLocation{coords:loc.coords,id:loc.id,operation:op,control:false});w.tick_with_random(&mut NoDraw).unwrap();}
#[test]fn five_hundred_four_initial_guards_conserve_whole_account(){let held=[24704,26879,28593,28595,28597,28599];let worn=[26822,26824,26826,26828,26830,26832,26834,26836,26838,26840,26842,26844,26846,26848,26850,26852,26854,26856,26858,26860,26862,26864,26866,26868,26870,26872,26874];let mut n=0;for row in 0..6{for member in[false,true]{for case in 0..42{let(mut w,a,loc,parts)=fixture(row,member,2,99,7,125);let mut op=1;match case{0=>{for(slot,_)in parts{w.data_mut(a).unwrap().inventory.restore_slot(slot,None).unwrap();}},1=>{w.data_mut(a).unwrap().stats.set_current(20,ROWS[row].2 as i8-1);},2=>w.delay_player(a,8).unwrap(),3=>w.set_modal_open(a,true).unwrap(),4=>{w.data_mut(a).unwrap().stats.set_current(3,0);},5=>w.request_logout(a).unwrap(),6=>op=2,7=>w.runecrafting=None,8=>{w.queue_hit(Target::Player(a),Hit{display:None,source:None,style:Style::Typeless,damage:20},1).unwrap();w.tick_with_random(&mut NoDraw).unwrap();assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::DeathRequested(_))));assert_eq!(w.data(a).unwrap().stats.current(3),0);w.data_mut(a).unwrap().stats.set_current(3,10);},_=>{let j=case-9;if j<6{w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:held[j],count:1,vars:0})).unwrap();}else{w.data_mut(a).unwrap().equipment.restore_slot(0,Some(Item{id:worn[j-6],count:1,vars:0})).unwrap();}}}let before=w.data(a).unwrap().clone();w.drain_events();attempt(&mut w,a,loc,op);for _ in 0..4{w.tick_with_random(&mut NoDraw).unwrap();}let d=w.data(a).unwrap();assert_eq!(d.inventory,before.inventory,"row{row} member{member} initialcase{case}");assert_eq!(d.equipment,before.equipment);assert_eq!(d.stats,before.stats);assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{..})));n+=1;}}}assert_eq!(n,504);println!("PG_RUNE_ALTARS initial whole-state refusals={n}");}
#[test]fn two_hundred_forty_late_material_context_and_credit_guards(){let mut n=0;for row in 0..6{for member in[false,true]{for case in 0..20{let(mut w,a,loc,parts)=fixture(row,member,2,99,7,125);request(&mut w,a,loc);let(slot,id)=parts[0];match case{0=>w.data_mut(a).unwrap().inventory.restore_slot(slot,None).unwrap(),1=>w.data_mut(a).unwrap().inventory.restore_slot(slot,Some(Item{id,count:1,vars:1})).unwrap(),2=>w.data_mut(a).unwrap().inventory.restore_slot(slot,Some(Item{id,count:2,vars:0})).unwrap(),3=>w.data_mut(a).unwrap().inventory.restore_slot(slot,Some(Item{id:if id==1436{7936}else{1436},count:1,vars:0})).unwrap(),4=>{w.data_mut(a).unwrap().stats.set_current(20,ROWS[row].2 as i8-1);},5=>w.data_mut(a).unwrap().xp_rate_hundreds=0,6=>w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:24704,count:1,vars:0})).unwrap(),7=>w.data_mut(a).unwrap().equipment.restore_slot(0,Some(Item{id:26850,count:1,vars:0})).unwrap(),8=>{w.set_modal_open(a,true).unwrap();w.close_dialogs(a).unwrap();w.set_modal_open(a,false).unwrap();},9=>{w.submit(a,Action::Walk{destination:CoordGrid::new(3220,3221,0).unwrap(),run:false}).unwrap();},10=>w.request_logout(a).unwrap(),11=>{w.data_mut(a).unwrap().stats.set_current(3,0);},12=>{w.locations.delete(loc);},13=>{w.locations.delete(loc);w.locations.load(loc);},14=>w.runecrafting=None,15=>w.runecrafting.as_mut().unwrap().altars.get_mut(&loc.id).unwrap().xp_tenths+=1,16=>{w.object_types.dummy.insert(ROWS[row].1);},17=>{w.object_types.stackable.remove(&ROWS[row].1);},18=>{w.object_types.dummy.insert(id);},_=>{w.close_dialogs(a).unwrap();}}let before=w.data(a).unwrap().clone();w.drain_events();for _ in 0..4{w.tick_with_random(&mut NoDraw).unwrap();}let d=w.data(a).unwrap();assert_eq!(d.inventory,before.inventory,"row{row} member{member} latecase{case}");assert_eq!(d.equipment,before.equipment);assert_eq!(d.stats,before.stats);assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{..})));n+=1;}}}assert_eq!(n,240);println!("PG_RUNE_ALTARS late whole-state refusals={n}");}
#[test]fn twelve_delayed_queue_then_real_close_cancellation_controls(){let mut n=0;for row in 0..6{for member in[false,true]{let(mut w,a,loc,_)=fixture(row,member,2,99,7,125);request(&mut w,a,loc);w.delay_player(a,8).unwrap();let before=w.data(a).unwrap().clone();for _ in 0..3{w.tick_with_random(&mut NoDraw).unwrap();assert!(w.protection(a).unwrap().delayed());assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert_eq!(w.data(a).unwrap().stats,before.stats);}w.close_dialogs(a).unwrap();for _ in 0..10{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert_eq!(w.data(a).unwrap().equipment,before.equipment);assert_eq!(w.data(a).unwrap().stats,before.stats);n+=1;}}assert_eq!(n,12);println!("PG_RUNE_ALTARS delayed+close controls={n};delayparkingnotcancellationuntilrealclose");}
